import java.util.Scanner;

public class OBADef {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long number = scanner.nextLong();
        int length = (int) (Math.log10(Math.abs(number)) + 1);
        System.out.println("" + calculate(number, length));
    }

    public static long generateSequence(long n) {
        return (long) (Math.pow(10, n) - 1) / 9;
    }

    public static long calculate(long n, int len) {
        long ones = generateSequence(len);
        long count = (n / ones) * len;
        n %= ones;
        if (n == 0) return count;
        long optionA = (len + 1) + calculate(ones - n, len - 1);
        long optionB = calculate(n, len - 1);
        return count + Math.min(optionA, optionB);
    }
}
